// Local-only mode works without Firebase account permissions. Enable cloud sync
// later when Authentication, Firestore rules, and Hosting access are available.
const CLOUD_ENABLED = false;
const WORKSPACE_ID = 'main';
const DEFAULT_CHECKLIST = ['Pressure gauge in green', 'Safety pin and tamper seal intact', 'Hose and nozzle clear', 'Extinguisher accessible and unobstructed', 'No visible damage or corrosion', 'Operating label legible'];
// Start empty so example assets cannot be mistaken for real safety records.
const demoFleet = [];
const demoInspections = [];

let app, auth, db, user=null, fleet=[], inspections=[], checklist=[...DEFAULT_CHECKLIST], activeView='overview', searchText='', fleetFilter='all', selectedLabelIds=new Set(), toastTimer, stopFleet, stopInspections, scannerStream, scannerTimer, scannerControls, pendingImports=[];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toISOString().slice(0,10); const dateFmt=d=>d?new Date(`${d}T12:00:00`).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}):'—';
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
function storeDemo(){localStorage.setItem('et-local-fleet-v1',JSON.stringify(fleet));localStorage.setItem('et-local-inspections-v1',JSON.stringify(inspections));localStorage.setItem('et-local-checklist-v1',JSON.stringify(checklist))}
function loadDemo(){fleet=JSON.parse(localStorage.getItem('et-local-fleet-v1')||'null')??structuredClone(demoFleet);inspections=JSON.parse(localStorage.getItem('et-local-inspections-v1')||'null')??structuredClone(demoInspections);checklist=JSON.parse(localStorage.getItem('et-local-checklist-v1')||'null')||[...DEFAULT_CHECKLIST]}
function setCloudLabel(label,online=false){$('#syncLabel').textContent=label;$('.sync-state i').style.background=online?'#56a66c':'#c8974a'}
function startCloudListeners(){if(stopFleet)stopFleet();if(stopInspections)stopInspections();const fcol=collection(db,'workspaces',WORKSPACE_ID,'extinguishers'),icol=collection(db,'workspaces',WORKSPACE_ID,'inspections');stopFleet=onSnapshot(fcol,s=>{fleet=s.docs.map(d=>({id:d.id,...d.data()}));render()},e=>toast('Could not load fleet: '+e.message));stopInspections=onSnapshot(icol,s=>{inspections=s.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>(b.date||'').localeCompare(a.date||''));render()},e=>toast('Could not load inspections: '+e.message));setCloudLabel('Shared cloud data · synced',true)}
async function saveRecord(kind,record){if(CLOUD_ENABLED&&user){const ref=doc(db,'workspaces',WORKSPACE_ID,kind,record.id);await setDoc(ref,{...record,updatedAt:serverTimestamp()},{merge:true})}else{if(kind==='extinguishers')fleet=fleet.filter(x=>x.id!==record.id).concat(record);else inspections=inspections.filter(x=>x.id!==record.id).concat(record);storeDemo();render()}}
async function saveBatch(kind,records){if(CLOUD_ENABLED&&user){for(let i=0;i<records.length;i+=400){const batch=writeBatch(db);records.slice(i,i+400).forEach(r=>batch.set(doc(db,'workspaces',WORKSPACE_ID,kind,r.id),{...r,updatedAt:serverTimestamp()},{merge:true}));await batch.commit()}}else{if(kind==='extinguishers')records.forEach(r=>{fleet=fleet.filter(x=>x.id!==r.id);fleet.push(r)});else records.forEach(r=>inspections.unshift(r));storeDemo();render()}}
async function removeAsset(id){if(CLOUD_ENABLED&&user)await deleteDoc(doc(db,'workspaces',WORKSPACE_ID,'extinguishers',id));else{fleet=fleet.filter(x=>x.id!==id);storeDemo();render()}}
function assetStatus(a){if(a.status==='failed')return'overdue';const d=a.expiry?Math.ceil((new Date(`${a.expiry}T12:00:00`)-new Date(`${today()}T12:00:00`))/86400000):99999;if(d<0)return'overdue';if(d<=60)return'due';const last=a.lastInspection?Math.ceil((new Date(`${today()}T12:00:00`)-new Date(`${a.lastInspection}T12:00:00`))/86400000):99999;return last>30?'due':'good'}
function statusPill(s){const labels={good:'In service',due:'Due soon',overdue:'Overdue',Pass:'Pass',Fail:'Fail',NeedsService:'Needs service'};return `<span class="status ${s==='Pass'?'pass':s==='Fail'||s==='NeedsService'?'failed':s}">${labels[s]||s}</span>`}
function assetById(id){return fleet.find(x=>x.id.toLowerCase()===String(id||'').toLowerCase())}
function render(){if(!$('#viewContent'))return;$('#fleetNavCount').textContent=fleet.length;$('#inspectionNavCount').textContent=inspections.length;$('#crumbCurrent').textContent={overview:'Overview',fleet:'Extinguisher fleet',inspections:'Inspections',reports:'Reports',settings:'Settings'}[activeView]||'Overview';$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===activeView));$('#viewContent').innerHTML=({overview:overviewView,fleet:fleetView,inspections:inspectionsView,reports:reportsView,settings:settingsView}[activeView]||overviewView)();bindViewEvents()}
function pageHead(kicker,title,subtitle,button=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div>${button}</div>`}
function overviewView(){const statuses=fleet.map(a=>[a,assetStatus(a)]),due=statuses.filter(x=>x[1]==='due').length,over=statuses.filter(x=>x[1]==='overdue').length,active=inspections.filter(x=>x.date?.slice(0,7)===today().slice(0,7)).length;const recent=[...inspections].sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,5);const alerts=statuses.filter(x=>x[1]!=='good').sort((a,b)=>a[1]==='overdue'?-1:1).slice(0,4);return `${pageHead(new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}).toUpperCase(),'Fleet overview','Here’s what’s happening across your extinguisher fleet.',`<button class="button primary" data-action="inspection">＋ Log inspection</button>`)}<div class="metric-grid"><div class="metric-card"><div class="metric-top">Total extinguishers <span class="metric-icon">▤</span></div><div class="metric-value">${fleet.length}</div><div class="metric-foot">Across ${new Set(fleet.map(a=>a.location).filter(Boolean)).size} locations</div></div><div class="metric-card"><div class="metric-top">In good standing <span class="metric-icon">✓</span></div><div class="metric-value">${statuses.filter(x=>x[1]==='good').length}</div><div class="metric-foot">${fleet.length?Math.round(statuses.filter(x=>x[1]==='good').length/fleet.length*100):0}% of your fleet</div></div><div class="metric-card"><div class="metric-top">Due for attention <span class="metric-icon">◷</span></div><div class="metric-value">${due+over}</div><div class="metric-foot warn">${over} overdue · ${due} due within 60 days</div></div><div class="metric-card"><div class="metric-top">Inspections this month <span class="metric-icon">☑</span></div><div class="metric-value">${active}</div><div class="metric-foot">${inspections.filter(i=>i.result==='Fail').length} need follow-up</div></div></div><div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h2>Recent inspections</h2><p>Your team's latest activity</p></div><button class="link-button" data-view="inspections">View all →</button></div>${recent.length?`<div class="table-wrap"><table><thead><tr><th>ASSET</th><th>LOCATION</th><th>INSPECTED</th><th>INSPECTOR</th><th>RESULT</th></tr></thead><tbody>${recent.map(i=>{let a=assetById(i.assetId)||{};return `<tr><td><span class="asset-id">${esc(i.assetId)}</span><br><span class="subtle-text">${esc(a.name||'Asset record')}</span></td><td>${esc(i.location||a.location||'—')}</td><td>${dateFmt(i.date)}</td><td>${esc(i.inspector||'—')}</td><td>${statusPill(i.result||'Pass')}</td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty-state"><strong>No inspections yet</strong><span>Log your first extinguisher inspection.</span></div>`}<div class="panel-body"><div class="quick-actions"><button class="quick-tile" data-action="inspection"><span class="quick-glyph">☑</span><strong>Log an inspection</strong><small>Record a completed check</small></button><button class="quick-tile" data-action="import-logs"><span class="quick-glyph">⇧</span><strong>Import inspection logs</strong><small>Reconcile your existing records</small></button><button class="quick-tile" data-action="asset"><span class="quick-glyph">＋</span><strong>Add extinguisher</strong><small>Register a new asset</small></button></div></div></section><section class="panel"><div class="panel-header"><div><h2>Needs attention</h2><p>Items to review soon</p></div><button class="link-button" data-view="fleet">View fleet →</button></div><div class="panel-body">${alerts.length?alerts.map(([a,s])=>`<div class="alert-row"><i class="alert-dot ${s==='overdue'?'red':''}"></i><div><strong>${esc(a.id)} · ${esc(a.name)}</strong><p>${s==='overdue'?'Service or expiry is past due':'Expiry or inspection is coming up'} · ${esc(a.location||'Location not set')}</p></div></div>`).join(''):`<div class="empty-state"><strong>All clear</strong><span>No assets need attention right now.</span></div>`}</div></section></div>`}
function fleetRows(){return fleet.filter(a=>(!searchText||[a.id,a.name,a.type,a.location,a.serial].some(x=>String(x||'').toLowerCase().includes(searchText)))&&(fleetFilter==='all'||assetStatus(a)===fleetFilter)).map(a=>`<tr><td><input type="checkbox" data-label-select data-id="${esc(a.id)}" ${selectedLabelIds.has(a.id)?'checked':''} aria-label="Select ${esc(a.id)} label"></td><td><span class="asset-id">${esc(a.id)}</span></td><td><strong>${esc(a.name||'—')}</strong></td><td>${esc(a.type||'—')}</td><td>${esc(a.size||'—')}</td><td>${esc(a.location||'—')}</td><td>${dateFmt(a.expiry)}</td><td>${dateFmt(a.lastInspection)}</td><td>${statusPill(assetStatus(a))}</td><td><button class="link-button" data-action="asset-edit" data-id="${esc(a.id)}">Edit</button> <button class="link-button" data-action="label" data-id="${esc(a.id)}" title="Print QR and barcode label">Print label</button></td></tr>`).join('')}
function fleetView(){return `${pageHead('ASSET REGISTER','Extinguisher fleet','A single, current record for every extinguisher.',`<button class="button" data-action="import">⇧ Import fleet</button> <button class="button" data-action="print-selected-labels" id="printSelectedLabels" disabled>▧ Print selected <span id="selectedLabelCount">0</span></button> <button class="button" data-action="print-labels" ${fleet.length?'':'disabled'}>Print all labels</button> <button class="button primary" data-action="asset">＋ Add extinguisher</button>`)}<div class="toolbar"><label class="search-box"><span>⌕</span><input id="fleetSearch" placeholder="Search ID, name or location…" value="${esc(searchText)}"></label><div class="filter-group"><select id="fleetFilter"><option value="all">All statuses</option><option value="good" ${fleetFilter==='good'?'selected':''}>In service</option><option value="due" ${fleetFilter==='due'?'selected':''}>Due soon</option><option value="overdue" ${fleetFilter==='overdue'?'selected':''}>Overdue</option></select><button class="button" data-action="scan">▣ Scan tag</button></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th class="label-select-head"><input type="checkbox" id="selectVisibleLabels" aria-label="Select all visible labels"></th><th>ASSET ID</th><th>NAME</th><th>TYPE</th><th>SIZE</th><th>LOCATION</th><th>EXPIRY</th><th>LAST INSPECTION</th><th>STATUS</th><th></th></tr></thead><tbody>${fleetRows()}</tbody></table></div>${fleet.length?`<div class="pagination"><span>Showing ${fleet.filter(a=>(!searchText||[a.id,a.name,a.type,a.location,a.serial].some(x=>String(x||'').toLowerCase().includes(searchText)))&&(fleetFilter==='all'||assetStatus(a)===fleetFilter)).length} of ${fleet.length} extinguishers</span><button class="link-button" data-action="export-fleet">Export CSV ↓</button></div>`:`<div class="empty-state"><strong>Your fleet starts here</strong><span>Add an extinguisher or import your current asset register.</span><p><button class="button primary" data-action="asset">Add first extinguisher</button> <button class="button" data-action="import">Import CSV</button></p></div>`}</section>`}
function inspectionsView(){const sorted=[...inspections].sort((a,b)=>(b.date||'').localeCompare(a.date||''));return `${pageHead('FIELD ACTIVITY','Inspections','A clear history of checks, results, and follow-up.',`<button class="button" data-action="import-logs">⇧ Import existing logs</button> <button class="button primary" data-action="inspection">＋ Log inspection</button>`)}<div class="toolbar"><label class="search-box"><span>⌕</span><input id="inspectionSearch" placeholder="Search asset, inspector, location…"></label><div class="filter-group"><button class="button" data-action="scan">▣ Scan tag</button></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>INSPECTION</th><th>ASSET</th><th>LOCATION</th><th>DATE</th><th>INSPECTOR</th><th>RESULT</th><th>NOTES</th></tr></thead><tbody id="inspectionRows">${sorted.map(i=>{const a=assetById(i.assetId)||{};return `<tr data-search="${esc(`${i.assetId} ${a.name||''} ${i.inspector||''} ${i.location||a.location||''} ${i.notes||''}`.toLowerCase())}"><td><strong>${esc(i.id)}</strong></td><td><span class="asset-id">${esc(i.assetId)}</span><br><span class="subtle-text">${esc(a.name||'Unmatched asset')}</span></td><td>${esc(i.location||a.location||'—')}</td><td>${dateFmt(i.date)}</td><td>${esc(i.inspector||'—')}</td><td>${statusPill(i.result||'Pass')}</td><td>${esc(i.notes||'—')}</td></tr>`}).join('')}</tbody></table></div>${!sorted.length?`<div class="empty-state"><strong>No inspection history yet</strong><span>Record an inspection or import your paper logs after transcription.</span></div>`:''}<div class="pagination"><span>${inspections.length} recorded inspections</span><button class="link-button" data-action="export-inspections">Export CSV ↓</button></div></section>`}
function reportsView(){return `${pageHead('RECORDS & EXPORTS','Reports','Export a snapshot of your fleet or inspection history.',`<button class="button" data-action="export-fleet">Export fleet CSV ↓</button>`)}<div class="report-grid"><article class="report-card"><div class="quick-glyph">▤</div><h3>Extinguisher fleet register</h3><p>Asset IDs, types, agent, size, location, expiry dates, inspection date, and current status.</p><div class="report-meta">${fleet.length} assets · updated now</div><button class="button" data-action="export-fleet">Download CSV ↓</button> <button class="button" data-action="print-fleet">Print / Save PDF</button></article><article class="report-card"><div class="quick-glyph">☑</div><h3>Inspection history</h3><p>Inspection dates, inspector names, results, checklist responses, locations, and notes.</p><div class="report-meta">${inspections.length} inspections · all dates</div><button class="button" data-action="export-inspections">Download CSV ↓</button> <button class="button" data-action="print-inspections">Print / Save PDF</button></article><article class="report-card"><div class="quick-glyph">◷</div><h3>Due and overdue assets</h3><p>Extinguishers with an upcoming inspection or expiry date, or a failed inspection.</p><div class="report-meta">${fleet.filter(a=>assetStatus(a)!=='good').length} items need attention</div><button class="button" data-action="export-due">Download CSV ↓</button> <button class="button" data-action="print-due">Print / Save PDF</button></article><article class="report-card"><div class="quick-glyph">⇧</div><h3>Import and reconciliation</h3><p>Bring in spreadsheet logs or manually transcribed paper records, review matches and proposed fleet changes.</p><div class="report-meta">Changes require review before saving</div><button class="button primary" data-action="import">Start an import</button></article><article class="report-card"><div class="quick-glyph">⇄</div><h3>Move data between devices</h3><p>Create a complete backup containing the fleet, inspection history, and checklist. Restore it on another device to merge records.</p><div class="report-meta">${fleet.length} assets · ${inspections.length} inspections · ${checklist.length} checklist items</div><button class="button" data-action="export-backup">Download backup JSON ↓</button> <button class="button" data-action="import-backup">Restore backup ↑</button><input id="backupFile" type="file" accept=".json,application/json" hidden></article></div><div class="warning-note" style="margin-top:15px">Keep a current backup and upload it on each device when you want to transfer updates. Restoring merges records by ID and replaces that device's checklist with the backup checklist. PDF reports open the browser's print dialog; choose “Save as PDF”.</div>`}
function settingsView(){return `${pageHead('WORKSPACE PREFERENCES','Settings','Set your team checklist and account preferences.')}<div class="settings-grid"><section class="settings-card"><h2>Inspection checklist</h2><p>Choose the checks your inspectors see. A failed item marks the inspection for follow-up.</p><div id="checklistEditor" class="checklist-editor">${checklist.map((c,i)=>`<div class="checklist-item"><input data-check-index="${i}" value="${esc(c)}"><button data-action="remove-check" data-index="${i}" title="Remove">×</button></div>`).join('')}</div><button class="button" data-action="add-check">＋ Add checklist item</button> <button class="button primary" data-action="save-checklist">Save checklist</button></section><section class="settings-card"><h2>Cloud sync & team access</h2><p>${CLOUD_ENABLED?'Firebase is configured. Sign in with an account already added to your Firebase Authentication project.':'This edition saves data only in this browser on this device. It does not sync across team members. Shared sync requires Firebase project permissions that are not available to the current account.'}</p><div class="warning-note">New accounts are not created in the app. Create team member accounts in Firebase Authentication and add their membership in Firestore so only approved users can access shared records.</div><p><strong>Workspace:</strong> ${esc(WORKSPACE_ID)} · <strong>Checklist items:</strong> ${checklist.length}</p>${CLOUD_ENABLED?'':'<button class="button" data-action="show-setup">View Firebase setup</button>'}</section></div>`}
function bindViewEvents(){const syncLabelSelection=()=>{const btn=$('#printSelectedLabels'),count=$('#selectedLabelCount');if(btn)btn.disabled=selectedLabelIds.size===0;if(count)count.textContent=selectedLabelIds.size;const selectAll=$('#selectVisibleLabels');if(selectAll){const boxes=$$('[data-label-select]');selectAll.checked=boxes.length>0&&boxes.every(x=>x.checked);selectAll.indeterminate=boxes.some(x=>x.checked)&&!selectAll.checked}};const bindLabelBoxes=()=>{$$('[data-label-select]').forEach(x=>x.onchange=()=>{if(x.checked)selectedLabelIds.add(x.dataset.id);else selectedLabelIds.delete(x.dataset.id);syncLabelSelection()});syncLabelSelection()};const selectAll=$('#selectVisibleLabels');if(selectAll)selectAll.onchange=()=>{$$('[data-label-select]').forEach(x=>{x.checked=selectAll.checked;if(x.checked)selectedLabelIds.add(x.dataset.id);else selectedLabelIds.delete(x.dataset.id)});syncLabelSelection()};bindLabelBoxes();const fs=$('#fleetSearch');if(fs)fs.oninput=e=>{searchText=e.target.value.toLowerCase();const body=$('.table-wrap tbody');if(body){body.innerHTML=fleetRows();bindLabelBoxes()}};const ff=$('#fleetFilter');if(ff)ff.onchange=e=>{fleetFilter=e.target.value;render()};const is=$('#inspectionSearch');if(is)is.oninput=e=>$$('#inspectionRows tr').forEach(r=>r.hidden=!r.dataset.search.includes(e.target.value.toLowerCase()));$$('[data-view]').forEach(b=>b.onclick=()=>{activeView=b.dataset.view;searchText='';render()});$$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset.id,b.dataset.index))}
function action(name,id,index){if(name==='asset')openAsset();if(name==='asset-edit')openAsset(assetById(id));if(name==='inspection')openInspection(id);if(name==='import'||name==='import-logs')openImport(name==='import-logs'?'logs':'fleet');if(name==='scan')openScanner();if(name==='label')openLabel(assetById(id));if(name==='print-labels')printFleetLabels();if(name==='print-selected-labels')printSelectedLabels();if(name==='export-fleet')exportCSV(fleet,'extinguisher-fleet.csv');if(name==='export-inspections')exportCSV(inspections,'inspection-history.csv');if(name==='export-due')exportCSV(fleet.filter(a=>assetStatus(a)!=='good'),'due-extinguishers.csv');if(name==='export-backup')downloadBackup();if(name==='import-backup')chooseBackupFile();if(name==='print-fleet')printReport('Extinguisher Fleet Register',fleet);if(name==='print-inspections')printReport('Inspection History',inspections);if(name==='print-due')printReport('Due and Overdue Extinguishers',fleet.filter(a=>assetStatus(a)!=='good'));if(name==='add-check'){checklist.push('New checklist item');render()}if(name==='remove-check'){checklist.splice(Number(index),1);render()}if(name==='save-checklist'){checklist=$$('#checklistEditor input').map(x=>x.value.trim()).filter(Boolean);if(CLOUD_ENABLED&&user)setDoc(doc(db,'workspaces',WORKSPACE_ID,'settings','inspection'),{checklist}).then(()=>toast('Checklist saved for the team.'));else{storeDemo();toast('Checklist saved in this browser.')}render()}if(name==='show-setup')openSetup()}
function modal(title,subtitle,body,foot='',large=false){$('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal ${large?'large':''}"><header class="modal-head"><div><h2>${title}</h2><p>${subtitle||''}</p></div><button class="modal-close" data-close>×</button></header><div class="modal-body">${body}</div>${foot?`<footer class="modal-foot">${foot}</footer>`:''}</section></div>`;$('#modalRoot').querySelector('[data-close]').onclick=closeModal;$('#modalRoot').querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()}}
function closeModal(){stopScanner();$('#modalRoot').innerHTML=''}
function openAsset(a={}){const edit=Boolean(a.id);modal(edit?'Edit extinguisher':'Add extinguisher','Asset records are shared with your team.',`<form id="assetForm"><div class="field-grid"><div class="field"><label>Extinguisher ID *</label><input name="id" required value="${esc(a.id||'')}" ${edit?'readonly':''} placeholder="e.g. EXT-009"></div><div class="field"><label>Asset name *</label><input name="name" required value="${esc(a.name||'')}" placeholder="e.g. West stairwell"></div><div class="field"><label>Extinguisher type *</label><input name="type" required value="${esc(a.type||'')}" placeholder="e.g. ABC Dry Chemical"></div><div class="field"><label>Contents / agent</label><input name="content" value="${esc(a.content||'')}" placeholder="e.g. Monoammonium phosphate"></div><div class="field"><label>Size / capacity</label><input name="size" value="${esc(a.size||'')}" placeholder="e.g. 10 lb"></div><div class="field"><label>Location</label><input name="location" value="${esc(a.location||'')}" placeholder="Building · floor · area"></div><div class="field"><label>Expiry / service date</label><input type="date" name="expiry" value="${esc(a.expiry||'')}"></div><div class="field"><label>Last inspection date</label><input type="date" name="lastInspection" value="${esc(a.lastInspection||'')}"></div><div class="field"><label>Serial number</label><input name="serial" value="${esc(a.serial||'')}"></div><div class="field"><label>Notes</label><input name="notes" value="${esc(a.notes||'')}"></div></div><div id="assetError" class="error-text"></div></form>`,`${edit?'<button class="button danger" id="deleteAsset">Delete asset</button>':'<span></span>'}<div><button class="button" data-close>Cancel</button> <button class="button primary" id="saveAsset">${edit?'Save changes':'Add to fleet'}</button></div>`);const save=$('#saveAsset');save.onclick=async()=>{const f=new FormData($('#assetForm'));const obj=Object.fromEntries(f.entries());obj.id=obj.id.trim().toUpperCase();obj.status='good';if(!obj.id||!obj.name||!obj.type){$('#assetError').textContent='ID, name, and type are required.';return}if(!edit&&assetById(obj.id)){ $('#assetError').textContent='That extinguisher ID already exists.';return}try{const saved={...a,...obj};await saveRecord('extinguishers',saved);closeModal();if(edit)toast('Extinguisher saved.');else openLabel(saved)}catch(e){$('#assetError').textContent=e.message}};const del=$('#deleteAsset');if(del)del.onclick=async()=>{if(confirm(`Delete ${a.id} from the fleet? Inspection history will remain.`)){await removeAsset(a.id);closeModal();toast('Asset deleted.')}};$('#modalRoot').querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal)}
function openInspection(assetId=''){const a=assetById(assetId);modal('Log an inspection','Check each item to confirm it passes. Any unchecked item marks the extinguisher for follow-up.',`<form id="inspectionForm"><div class="field-grid"><div class="field"><label>Extinguisher *</label><select name="assetId" required><option value="">Select an asset</option>${fleet.map(x=>`<option value="${esc(x.id)}" ${x.id===assetId?'selected':''}>${esc(x.id)} · ${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Inspection date *</label><input name="date" type="date" required value="${today()}"></div><div class="field"><label>Inspector *</label><input name="inspector" required value="${esc(user?.email?.split('@')[0]||'Jordan Davis')}"></div><div class="field"><label>Location</label><input name="location" value="${esc(a?.location||'')}"></div></div><div class="eyebrow" style="margin-top:10px">INSPECTION CHECKLIST</div><div class="checkbox-grid">${checklist.map((x,i)=>`<label class="checkline"><input type="checkbox" name="check-${i}"><span>${esc(x)}</span></label>`).join('')}</div><div class="field" style="margin-top:12px"><label>Notes / corrective action</label><textarea name="notes" placeholder="Record defects, actions taken, or follow-up required"></textarea></div></form><div id="inspectionError" class="error-text"></div>`,`<button class="button" data-close>Cancel</button><button class="button" id="scanInspectionBarcode">Scan barcode</button><button class="button primary" id="saveInspection">Save inspection</button>`);$('#scanInspectionBarcode').onclick=()=>openScanner();$('#saveInspection').onclick=async()=>{const f=new FormData($('#inspectionForm')),asset=assetById(f.get('assetId'));if(!asset){$('#inspectionError').textContent='Choose an extinguisher from the fleet.';return}const checks=checklist.map((label,i)=>({label,pass:Boolean($('#inspectionForm').elements[`check-${i}`]?.checked)}));const result=checks.every(x=>x.pass)?'Pass':'Fail';const id='IN-'+Date.now().toString().slice(-7);const record={id,assetId:asset.id,date:f.get('date'),inspector:f.get('inspector'),location:f.get('location')||asset.location||'',result,notes:f.get('notes'),checks};try{await saveRecord('inspections',record);await saveRecord('extinguishers',{...asset,lastInspection:record.date,status:result==='Fail'?'failed':'good'});closeModal();toast(`Inspection saved · ${result}`);activeView='inspections';render()}catch(e){$('#inspectionError').textContent=e.message}};$('#modalRoot').querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal)}
function openImport(mode='fleet'){pendingImports=[];const title=mode==='logs'?'Import inspection logs':'Import extinguisher fleet';modal(title,'Upload a CSV/Excel workbook, or transcribe a paper/photo log into the review table before importing.',`<p class="import-note">${mode==='logs'?'Expected columns include ID, date, inspector, result (Pass/Fail), location, and notes. IDs missing from the fleet will create fleet records using details available in columns or labeled notes; missing type, contents, size, expiry, or location will stay blank for review.':'Expected columns include ID, name, type, contents, size, location, expiry, and last inspection. Column names are matched flexibly.'} CSV, XLS, and XLSX files are accepted (first worksheet). For photos or paper logs, review and transcribe each entry below; image text is not auto-read.</p><div class="field"><label>Upload spreadsheet</label><input id="importFile" type="file" accept=".csv,.xls,.xlsx,text/csv,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"></div><div class="field"><label>Or paste / transcribe rows as CSV</label><textarea id="importText" placeholder="${mode==='logs'?'ID, date, inspector, result, location, notes\nEXT-001, 2026-10-29, Team member, Pass, Lobby, OK':'ID, name, type, contents, size, location, expiry, last inspection\nEXT-009, East stairwell, ABC, Dry chemical, 10 lb, Building A, 2027-12-31, 2026-10-01'}"></textarea></div><div id="importError" class="error-text"></div><button class="button primary" id="previewImport">Preview & reconcile</button><div id="importPreview"></div>`,null,true);$('#importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(/\.xlsx?$/i.test(file.name)){if(!window.XLSX)throw Error('Spreadsheet reader did not load. Check your internet connection and try CSV instead.');const workbook=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false});const first=workbook.Sheets[workbook.SheetNames[0]];$('#importText').value=XLSX.utils.sheet_to_csv(first)}else $('#importText').value=await file.text()}catch(err){$('#importError').textContent=err.message}};$('#previewImport').onclick=()=>previewImport(mode);}
function parseCSV(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++}else if(c==='"')quoted=false;else field+=c}else if(c==='"')quoted=true;else if(c===','){row.push(field.trim());field=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field.trim());if(row.some(Boolean))rows.push(row);row=[];field=''}else field+=c}if(field||row.length){row.push(field.trim());if(row.some(Boolean))rows.push(row)}if(rows.length<2)throw Error('Add a header row and at least one record.');const headers=rows.shift().map(h=>h.toLowerCase().replace(/[^a-z0-9]/g,''));const validHeaders=headers.map((h,i)=>[h,i]).filter(([h])=>h);return rows.map(cols=>Object.fromEntries(validHeaders.map(([h,i])=>[h,(cols[i]||'').trim()] )))}
function getField(row,names){for(const n of names){const key=n.toLowerCase().replace(/[^a-z0-9]/g,'');if(row[key])return row[key]}return''}
function noteField(notes,names){for(const name of names){const escaped=name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const m=String(notes||'').match(new RegExp(`(?:^|[|;,\\n])\\s*${escaped}\\s*:\\s*([^|;,\\n]+)`,'i'));if(m)return m[1].trim()}return''}
function assetDetailsFromLog(row,id,date){const notes=getField(row,['notes','comments','remarks']);const value=(fields,noteLabels=fields)=>getField(row,fields)||noteField(notes,noteLabels);const agent=value(['content','contents','agent','extinguishing agent'])||(notes.match(/\b(CO2|carbon dioxide|foam|water|dry chemical|dry powder|wet chemical|clean agent|halotron)\b/i)||[])[0]||'';const size=value(['size','capacity'])||(notes.match(/\b\d+(?:[.,]\d+)?\s*(?:kg|g|lb|lbs|l|litres?|liters?)\b/i)||[])[0]||'';const expiryText=value(['expiry','expiry date','service date','next service date'])||(notes.match(/(?:expir(?:y|es)|service due|next service|hydrostatic test expires?)[^\d]{0,24}((?:19|20)\d{2}[-/]\d{1,2}[-/]\d{1,2})/i)||[])[1]||'';return {id,name:value(['name','asset name','extinguisher name','description'])||`Extinguisher ${id}`,type:value(['type','extinguisher type','class']),content:agent,size,location:getField(row,['location','area','site']),expiry:normalDate(expiryText),lastInspection:date,serial:getField(row,['serial','serial number']),status:normalResult(getField(row,['result','status','inspection result']))==='Fail'?'failed':'good',notes:'Auto-added from an inspection log. Complete any missing fleet details.'}}
function missingAssetDetails(asset){return ['type','content','size','expiry','location'].filter(key=>!asset?.[key])}
function sameInspection(a,b){const norm=v=>String(v||'').trim().toLowerCase();return norm(a.assetId)===norm(b.assetId)&&normalDate(String(a.date||''))===normalDate(String(b.date||''))&&norm(a.inspector)===norm(b.inspector)&&norm(a.result)===norm(b.result)&&norm(a.location)===norm(b.location)&&norm(a.notes)===norm(b.notes)}
function previewImport(mode){const err=$('#importError'),out=$('#importPreview');try{const rows=parseCSV($('#importText').value),first=rows[0]||{},has=(names)=>names.some(n=>Object.prototype.hasOwnProperty.call(first,n.replace(/[^a-z0-9]/gi,'').toLowerCase()));if(mode==='fleet'&&has(['result','inspection result'])&&has(['inspector','inspected by','technician'])&&!has(['name','asset name','extinguisher name','type','extinguisher type','class']))throw Error('This looks like an inspection log, not a fleet register. Close this window and choose Import existing logs from the Inspections page.');const seen=new Set(),dupes=[];pendingImports=rows.map((r,i)=>{const id=getField(r,['id','asset id','extinguisher id','tag','tag id','equipment number','asset number']).toUpperCase();if(!id)throw Error(`Row ${i+2} has no asset ID.`);if(seen.has(id))dupes.push(id);seen.add(id);if(mode==='logs'){const date=normalDate(getField(r,['date','inspection date','inspected on']))||today(),details=assetDetailsFromLog(r,id,date);return {id:'IM-'+Date.now().toString().slice(-5)+'-'+i,assetId:id,date,inspector:getField(r,['inspector','inspected by','technician'])||'Imported log',result:normalResult(getField(r,['result','status','inspection result'])),location:getField(r,['location','area','site']),notes:getField(r,['notes','comments','remarks']),checks:[],_assetDetails:details,_matched:Boolean(assetById(id)),_raw:r}};return {id,name:getField(r,['name','asset name','extinguisher name','description']),type:getField(r,['type','extinguisher type','class']),content:getField(r,['content','contents','agent','extinguishing agent']),size:getField(r,['size','capacity']),location:getField(r,['location','area','site']),expiry:normalDate(getField(r,['expiry','expiry date','service date','next service date'])),lastInspection:normalDate(getField(r,['last inspection','inspection date','last inspected'])),serial:getField(r,['serial','serial number']),notes:getField(r,['notes','comments']),status:'good',_matched:Boolean(assetById(id)),_raw:r}});if(dupes.length)throw Error('Duplicate IDs in the import: '+[...new Set(dupes)].join(', '));if(mode==='logs')pendingImports.forEach(x=>x._duplicate=inspections.some(old=>sameInspection(old,x)));const duplicates=mode==='logs'?pendingImports.filter(x=>x._duplicate).length:0;const adds=pendingImports.filter(x=>!x._matched).length,updates=pendingImports.length-adds;err.textContent='';out.innerHTML=`<div class="success-note">${pendingImports.length} rows found · ${updates} matched to existing fleet records · ${adds} new asset IDs${mode==='logs'&&duplicates?` · ${duplicates} duplicate inspections will be skipped`:''}. Review proposed changes below before applying.</div><div class="import-preview"><table><thead><tr><th>ROW</th><th>ID</th><th>${mode==='logs'?'DATE / RESULT / EXTRACTED FLEET DETAILS':'NAME / TYPE'}</th><th>RECONCILIATION</th><th></th></tr></thead><tbody>${pendingImports.map((x,i)=>`<tr><td>${i+1}</td><td><span class="asset-id">${esc(x.id)}</span></td><td>${mode==='logs'?`${dateFmt(x.date)} · ${statusPill(x.result)}<br><span class="subtle-text">${esc(x._assetDetails.name)} · ${esc(x._assetDetails.type||'Type missing')} · ${esc(x._assetDetails.content||'Contents missing')} · ${esc(x._assetDetails.size||'Size missing')} · Expiry ${dateFmt(x._assetDetails.expiry)}</span>`:`${esc(x.name||'Name missing')} · ${esc(x.type||'Type missing')}`}</td><td>${x._duplicate?'Already imported · skip':x._matched?'Matched existing fleet ID':mode==='logs'?`Will add fleet record${missingAssetDetails(x._assetDetails).length?` · missing: ${missingAssetDetails(x._assetDetails).join(', ')}`:''}`:'New ID · will add to fleet'}</td><td><button class="link-button" data-import-edit="${i}">Edit row</button></td></tr>`).join('')}</tbody></table></div><p class="import-note">Matched assets will only have non-empty imported fields updated. New IDs will be added. ${mode==='logs'?'Log entries for IDs absent from the fleet will also create fleet records. Details missing from the log stay blank for later completion.':''}</p><button class="button primary" id="applyImport">Apply ${pendingImports.length} reviewed rows</button>`;$$('[data-import-edit]').forEach(b=>b.onclick=()=>editImportRow(Number(b.dataset.importEdit),mode));$('#applyImport').onclick=()=>applyImport(mode)}catch(e){err.textContent=e.message;out.innerHTML=''}}
function normalDate(s){if(!s)return'';const serial=Number(s);if(/^\d{5}(?:\.\d+)?$/.test(s)&&serial>=20000&&serial<=80000)return new Date(Date.UTC(1899,11,30)+Math.floor(serial)*86400000).toISOString().slice(0,10);const iso=s.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})$/);if(iso)return`${iso[1]}-${iso[2].padStart(2,'0')}-${iso[3].padStart(2,'0')}`;const us=s.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{2,4})$/);if(us)return`${us[3].length===2?'20'+us[3]:us[3]}-${us[1].padStart(2,'0')}-${us[2].padStart(2,'0')}`;return s}
function normalResult(s){s=s.toLowerCase();return /fail|defect|repair|service|not ok/.test(s)?'Fail':'Pass'}
function editImportRow(i,mode){const r=pendingImports[i];const raw=prompt(mode==='logs'?'Edit row as: ID | date | inspector | result | location | notes':'Edit row as: ID | name | type | contents | size | location | expiry | last inspection',mode==='logs'?[r.assetId,r.date,r.inspector,r.result,r.location,r.notes].join(' | '):[r.id,r.name,r.type,r.content,r.size,r.location,r.expiry,r.lastInspection].join(' | '));if(raw===null)return;const p=raw.split('|').map(s=>s.trim());if(mode==='logs')Object.assign(r,{assetId:p[0].toUpperCase(),date:normalDate(p[1])||today(),inspector:p[2]||'Imported log',result:normalResult(p[3]),location:p[4],notes:p[5]});else Object.assign(r,{id:p[0].toUpperCase(),name:p[1],type:p[2],content:p[3],size:p[4],location:p[5],expiry:normalDate(p[6]),lastInspection:normalDate(p[7])});previewImport(mode)}
async function applyImport(mode){
 const btn=$('#applyImport');btn.disabled=true;let importedCount=pendingImports.length,addedCount=0,duplicateCount=0;
 try{
  if(mode==='fleet'){
   const records=pendingImports.map(x=>{const clean=Object.fromEntries(Object.entries(x).filter(([k])=>!k.startsWith('_')));const old=assetById(x.id);return old?{...old,...Object.fromEntries(Object.entries(clean).filter(([,v])=>v!==''&&v!==undefined))}:clean});
   await saveBatch('extinguishers',records);
  }else{
   duplicateCount=pendingImports.filter(x=>x._duplicate).length;const records=pendingImports.filter(x=>!x._duplicate).map(x=>{const {_matched,_raw,_assetDetails,_duplicate,...r}=x;return r});importedCount=records.length;
   if(records.length)await saveBatch('inspections',records);
   const updates=new Map(),newAssets=[];
   pendingImports.forEach(i=>{const a=assetById(i.assetId);if(a)updates.set(a.id,{...a,lastInspection:i.date,status:i.result==='Fail'?'failed':'good'});else if(i._assetDetails)newAssets.push(i._assetDetails)});
   if(updates.size)await saveBatch('extinguishers',[...updates.values()]);
   if(newAssets.length)await saveBatch('extinguishers',newAssets);addedCount=newAssets.length;
  }
  closeModal();toast(mode==='logs'?importedCount+' inspections imported · '+addedCount+' fleet records added · '+duplicateCount+' duplicate inspections skipped.':pendingImports.length+' records imported. Review complete.');activeView=mode==='logs'?'inspections':'fleet';render();
 }catch(e){$('#importError').textContent='Could not import: '+e.message;btn.disabled=false}
}
function openScanner(){modal('Scan extinguisher tag','Point the camera at a QR code or barcode to open that asset or start its inspection.',`<div class="scan-wrap"><div class="scan-placeholder" id="scanMessage">Requesting camera access…</div><video id="scanVideo" class="hidden" playsinline></video><div class="scan-frame"></div></div><p class="import-note">Camera scanning requires a secure HTTPS page and browser permission. You can also enter the asset ID manually.</p><div class="field"><label>Asset ID</label><input id="manualScan" placeholder="e.g. EXT-001"></div>`,`<button class="button" data-close>Cancel</button><button id="manualScanGo" class="button primary">Open inspection</button>`);$('#manualScanGo').onclick=()=>{const v=$('#manualScan').value.trim();if(v)scannerResult(v)};startScanner()}
async function startScanner(){const video=$('#scanVideo'),message=$('#scanMessage');if('BarcodeDetector'in window){try{const detector=new BarcodeDetector({formats:['qr_code','code_128','code_39','ean_13','ean_8','upc_a','upc_e']});scannerStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});video.srcObject=scannerStream;video.classList.remove('hidden');message.classList.add('hidden');await video.play();const scan=async()=>{if(!scannerStream)return;try{const codes=await detector.detect(video);if(codes.length)scannerResult(codes[0].rawValue);else scannerTimer=setTimeout(scan,350)}catch{scannerTimer=setTimeout(scan,600)}};scan();return}catch(e){if(scannerStream){scannerStream.getTracks().forEach(t=>t.stop());scannerStream=null}}}if(window.ZXingBrowser?.BrowserMultiFormatReader){try{video.classList.remove('hidden');message.classList.remove('hidden');message.textContent='Starting camera…';const reader=new window.ZXingBrowser.BrowserMultiFormatReader();scannerControls=await reader.decodeFromVideoDevice(undefined,video,(result,error,controls)=>{if(result){scannerControls=controls;scannerResult(result.getText())}});message.classList.add('hidden');return}catch(e){if(scannerControls){scannerControls.stop();scannerControls=null}message.classList.remove('hidden');message.textContent='Camera unavailable. Allow camera access or enter the extinguisher ID below.';return}}message.classList.remove('hidden');message.textContent='Barcode scanner could not load. Check your internet connection or enter the extinguisher ID below.'}function stopScanner(){if(scannerTimer)clearTimeout(scannerTimer);scannerTimer=null;if(scannerControls){scannerControls.stop();scannerControls=null}if(scannerStream){scannerStream.getTracks().forEach(t=>t.stop());scannerStream=null}}
function scannerResult(value){stopScanner();let id=String(value||'').trim();try{const url=new URL(id);id=url.searchParams.get('asset')||id}catch{}const a=assetById(id);closeModal();if(a)openInspection(a.id);else{toast('No fleet record for '+id+'. Add or reconcile this ID first.');activeView='fleet';render()}}
function assetQrUrl(id){const url=new URL(window.location.href);url.search='';url.hash='';url.searchParams.set('asset',id);return url.toString()}
function labelMarkup(a){return '<article class="label-print"><div class="label-code" data-asset-id="'+esc(a.id)+'"><div class="qr-box qr-code"></div><svg class="barcode"></svg></div><div class="label-info"><div class="label-brand">EXTINGUISHER TRACKER</div><strong class="label-asset-id">'+esc(a.id)+'</strong><div class="label-name">'+esc(a.name||'Fire extinguisher')+'</div><div class="label-meta">'+esc([a.type,a.size].filter(Boolean).join(' · '))+'</div><div class="label-location">'+esc(a.location||'')+'</div><div class="label-instruction">Scan the QR with your phone camera to open this extinguisher and log an inspection.</div></div></article>'}
async function fillLabelCodes(scope){const status=scope.querySelector('#labelGeneratorStatus');for(let i=0;i<20&&(!window.QRCode||!window.JsBarcode);i++)await new Promise(resolve=>setTimeout(resolve,150));let failed=false;scope.querySelectorAll('.label-code').forEach(box=>{const id=box.dataset.assetId,qr=box.querySelector('.qr-code'),barcode=box.querySelector('.barcode');try{if(!window.QRCode)throw Error('QR library unavailable');new window.QRCode(qr,{text:assetQrUrl(id),width:112,height:112,colorDark:'#18251d',colorLight:'#ffffff',correctLevel:window.QRCode.CorrectLevel.M})}catch{failed=true;qr.textContent='QR code unavailable'}try{if(!window.JsBarcode)throw Error('Barcode library unavailable');window.JsBarcode(barcode,id,{format:'CODE128',width:1.5,height:38,displayValue:true,fontSize:11,margin:3})}catch{failed=true;barcode.insertAdjacentHTML('afterend','<span class="code-error">Barcode unavailable</span>')}});if(status)status.textContent=failed?'A code could not be generated. Check your internet connection and reopen the label.':'QR and barcode generated. Print, cut out, and attach this label.';scope.querySelectorAll('[data-print-labels]').forEach(button=>button.disabled=failed)}
function openLabel(a){if(!a){toast('Asset not found');return}modal('Print extinguisher label',a.id+' · '+(a.name||''),'<div class="single-label">'+labelMarkup(a)+'</div><p id="labelGeneratorStatus" class="import-note">Generating QR and barcode…</p>','<button class="button" data-close>Close</button><button class="button primary" data-print-labels disabled>Print label</button>');fillLabelCodes($('#modalRoot'));$('#modalRoot').querySelector('[data-print-labels]').onclick=()=>window.print();$('#modalRoot').querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal)}
function printLabelRecords(records,title){modal(title,records.length+' labels · print, cut, and attach to the selected extinguisher'+(records.length===1?'':'s')+'.','<div class="label-sheet">'+records.map(labelMarkup).join('')+'</div><p id="labelGeneratorStatus" class="import-note">Generating QR codes and barcodes for '+records.length+' extinguishers…</p>','<button class="button" data-close>Close</button><button class="button primary" data-print-labels disabled>Print '+(records.length===1?'label':'selected labels')+'</button>',true);fillLabelCodes($('#modalRoot'));$('#modalRoot').querySelector('[data-print-labels]').onclick=()=>window.print();$('#modalRoot').querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal)}
function printSelectedLabels(){const selected=fleet.filter(a=>selectedLabelIds.has(a.id));if(!selected.length){toast('Select at least one extinguisher label first.');return}printLabelRecords(selected,`Print selected labels (${selected.length})`)}
function printFleetLabels(){if(!fleet.length){toast('Add or import extinguishers before printing labels.');return}printLabelRecords(fleet,'Print all extinguisher labels')}
function exportCSV(rows,filename){if(!rows.length){toast('No records to export.');return}const keys=[...new Set(rows.flatMap(r=>Object.keys(r).filter(k=>!k.startsWith('_')&&k!=='updatedAt')))];const cell=v=>`"${String(Array.isArray(v)?JSON.stringify(v):v??'').replaceAll('"','""')}"`;const csv=[keys.join(','),...rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=filename;a.click();URL.revokeObjectURL(a.href);toast('CSV downloaded.')}
function downloadBackup(){const backup={format:'extinguisher-tracker-backup',version:1,exportedAt:new Date().toISOString(),fleet,inspections,checklist};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}));a.download=`extinguisher-tracker-backup-${today()}.json`;a.click();URL.revokeObjectURL(a.href);toast('Full device backup downloaded.')}
function chooseBackupFile(){const input=$('#backupFile');if(!input)return;input.value='';input.onchange=()=>restoreBackupFile(input.files?.[0]);input.click()}
async function restoreBackupFile(file){if(!file)return;try{if(file.size>20*1024*1024)throw Error('Backup is larger than 20 MB.');const data=JSON.parse(await file.text());if(data.format!=='extinguisher-tracker-backup'||data.version!==1)throw Error('This is not a supported Extinguisher Tracker backup.');if(!Array.isArray(data.fleet)||!Array.isArray(data.inspections)||!Array.isArray(data.checklist))throw Error('Backup is missing fleet, inspections, or checklist data.');if(data.fleet.some(x=>!x||typeof x.id!=='string'||!x.id.trim())||data.inspections.some(x=>!x||typeof x.id!=='string'||!x.id.trim()||typeof x.assetId!=='string'))throw Error('Backup contains a record without a valid ID.');if(data.checklist.length>100||data.checklist.some(x=>typeof x!=='string'))throw Error('Backup checklist is invalid or too large.');const incoming={fleet:data.fleet,inspections:data.inspections,checklist:data.checklist};modal('Review backup restore',`This backup contains ${incoming.fleet.length} extinguishers, ${incoming.inspections.length} inspections, and ${incoming.checklist.length} checklist items.`, `<div class="import-note">Records will merge with this device by ID. If an ID exists on both devices, the backup copy will replace that record. The checklist on this device will be replaced by the backup checklist.</div><div class="warning-note">Download a backup from this device first if you may need to undo this restore.</div>`, '<button class="button" data-close>Cancel</button><button class="button primary" id="applyBackup">Merge backup</button>');$('#applyBackup').onclick=()=>{const merge=(current,added)=>{const map=new Map(current.map(x=>[x.id.toLowerCase(),x]));added.forEach(x=>map.set(x.id.toLowerCase(),x));return [...map.values()]};fleet=merge(fleet,incoming.fleet);inspections=merge(inspections,incoming.inspections).sort((a,b)=>(b.date||'').localeCompare(a.date||''));checklist=[...incoming.checklist];storeDemo();closeModal();render();toast('Backup merged into this device.')};}catch(e){toast(`Could not restore backup: ${e.message}`)}}
function printReport(title,rows){const win=window.open('','_blank');if(!win){toast('Allow pop-ups to print this report.');return}const keys=[...new Set(rows.flatMap(r=>Object.keys(r).filter(k=>!k.startsWith('_')&&k!=='updatedAt')))];win.document.write(`<!doctype html><title>${esc(title)}</title><style>body{font:12px Arial;padding:24px;color:#222}h1{font-size:20px}p{color:#666;font-size:11px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ddd;padding:6px;text-align:left;font-size:10px}th{background:#f3f4f2}</style><h1>${esc(title)}</h1><p>Generated ${new Date().toLocaleString()} · ${rows.length} records</p><table><thead><tr>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${keys.map(k=>`<td>${esc(Array.isArray(r[k])?JSON.stringify(r[k]):r[k]||'')}</td>`).join('')}</tr>`).join('')}</tbody></table><script>window.onload=()=>window.print()<\/script>`);win.document.close()}
function openSetup(){modal('Shared sync unavailable','This edition runs in your browser without team sync.',`<p class="import-note">Fleet and inspection data stays on this device. Publishing the static app over HTTPS lets your phone use its camera, but does not share records with other devices.</p><div class="warning-note">Shared sync requires Firebase permissions that are not available to the current account.</div>`,'<button class="button primary" data-close>Got it</button>')}
$('#mainNav').onclick=e=>{const b=e.target.closest('[data-view]');if(b){activeView=b.dataset.view;searchText='';render()}};$('#settingsShortcut').onclick=()=>{activeView='settings';render()};$('#helpImport').onclick=()=>openImport('logs');
function openLinkedAssetFromUrl(){const id=new URLSearchParams(window.location.search).get('asset');if(!id)return;history.replaceState({},'',window.location.pathname+window.location.hash);let attempts=0;const open=()=>{const asset=assetById(id);if(asset){openInspection(asset.id);return}if(attempts++<24)setTimeout(open,250);else toast('No extinguisher with ID '+id+' is stored on this device. Import the fleet first.')};open()}
const appConfigured=CLOUD_ENABLED;
if(appConfigured){app=initializeApp(FIREBASE_CONFIG);auth=getAuth(app);db=getFirestore(app);onAuthStateChanged(auth,async u=>{user=u;if(!u){$('#appShell').classList.add('hidden');$('#authScreen').classList.remove('hidden');setCloudLabel('Sign in to sync');return}$('#authScreen').classList.add('hidden');$('#appShell').classList.remove('hidden');$('#userName').textContent=u.email?.split('@')[0]||'Team member';$('#userEmail').textContent=u.email;$('#userAvatar').textContent=(u.email||'U').slice(0,2).toUpperCase();$('#headerAvatar').textContent=(u.email||'U').slice(0,2).toUpperCase();startCloudListeners();openLinkedAssetFromUrl();try{const {getDoc}=await import('https://www.gstatic.com/firebasejs/10.14.1/firebase-firestore.js');const snap=await getDoc(doc(db,'workspaces',WORKSPACE_ID,'settings','inspection'));if(snap.exists()&&Array.isArray(snap.data().checklist)){checklist=snap.data().checklist;render()}}catch{}});$('#authForm').onsubmit=async e=>{e.preventDefault();$('#authError').textContent='';try{await signInWithEmailAndPassword(auth,$('#authEmail').value,$('#authPassword').value)}catch(err){$('#authError').textContent=err.message}};$('#authToggle').classList.add('hidden');$('#authTitle').textContent='Welcome back';$('#authSubmit').textContent='Sign in';$('#signOut').onclick=()=>signOut(auth)}else{$('#signOut').onclick=()=>toast('Local mode has no account session.');$('#userName').textContent='Local user';$('#userEmail').textContent='Saved on this device';$('#userAvatar').textContent='LU';$('#headerAvatar').textContent='LU';$('#workspaceName').textContent='Extinguisher Tracker';$('.workspace-chip small').textContent='This device only';loadDemo();setCloudLabel('Local data · this device');render();openLinkedAssetFromUrl()}







